figure.artwork:
Policy (Rego): -------------- package agent default allow = false
allow { input.action == "add_to_cart" input.amount <= 50.0 }
allow { input.action == "view_recommendations" }
Consent Display: ---------------- This agent is requesting permission to:
✓ Add items to your shopping cart (maximum $50 per item) ✓ View product recommendations for you
This agent CANNOT: ✗ Remove items from your cart ✗ Complete purchases or access payment methods ✗ Access your order history

{
  "active": true,
  "iss": "https://as.example.com",
  "sub": "user_12345",
  "aud": "https://api.shop.example.com",
  "exp": 1731369540,
  "iat": 1731320700,

  "act": {
    "sub": "wit://agent.example.com/sha256.abc123...",
    "agent_user_id": "agent_user_001"
  },

  "policy_ref": "policy-cart-50",
  "evidence_ref": "evidence-xyz",

  "policy_content": {
    "type": "rego",
    "content": "package agent\ndefault allow = false\nallow { input.amount <= 50 }",
    "entry_point": "allow"
  },

  "evidence_details": {
    "id": "evidence-xyz",
    "user_confirmation": {
      "displayed_content": "Add items under $50 to cart",
      "user_action": "confirmed_via_button_click",
      "timestamp": 1731320595
    },
    "as_signature": "eyJhbGciOiJSUzI1NiJ9..."
  }
}

